"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["23093"],{501168(e){e.exports=JSON.parse('{"id":7782,"title":"\u4F7F\u7528\u9AD8\u7EA7\u53E5\u578B\u81F3\u5C113\u4E2A\u3002","description":"A Beacon of Medical Integrity: The Legacy of Lan Yuefeng\\n\\nDear friends,\\n\\nI want to highlight Lan Yuefeng, a former ultrasound department director hailed as \\"China\u2019s medical conscience.\\" As a senior doctor, she bravely exposed over-treatment and false examinations at her hospital that exploited patients.\\n\\nDespite demotion, suspension, and pressure, she refused to compromise medical ethics, prioritizing patients\u2019 interests by declining unnecessary tests. Her courage sparked widespread social attention to healthcare irregularities, pushing industry standardization.\\n\\nLan\u2019s unwavering commitment to integrity embodies the true medical spirit. As future medics, let\u2019s inherit her courage\u2014uphold professional ethics, defend patient rights, and safeguard the nobility of medicine.\\n\\nThank you.","owner":"cc\u8521","upvotes":2,"downvotes":0,"upvoteDifference":2,"updatedAt":"2026-04-13T20:38:47.070Z"}')}}]);